CREATE COLUMN TABLE "TEST_AP"."OTRN" ("AbsEntry" INTEGER CS_INT NOT NULL , "Category" NVARCHAR(6) NOT NULL , "PriCode" NVARCHAR(128) NOT NULL , "SecCode" NVARCHAR(128) NOT NULL , "SourceLang" INTEGER CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTRN_CATCODE" ON "TEST_AP"."OTRN" ( "Category" ASC, "PriCode" ASC, "SecCode" ASC )